160	 * Measured on #12's thread against a real file on `main`.
161	 *
162	 * The path is percent-encoded per segment. A target is allowed to contain a space and
163	 * a `#`, both of which end the path in a URL — an unencoded `#` would make the link
164	 * open the branch at a fragment that does not exist, and a space is not even a legal
165	 * URL character. `encodeURIComponent` per segment rather than once over the whole
166	 * path, so the `/` separators survive.
167	 */
168	export function blobUrlFor(repo: string, branch: string, target: string): string {
169	  const path = target
170	    .split("/")
171	    .map((segment) => encodeURIComponent(segment))
172	    .join("/");
173	  return `https://github.com/${repo}/blob/${encodeURIComponent(branch)}/${path}`;
174	}
