176	/**
177	 * What `git update-index --index-info` is fed, in the `-z` form.
178	 *
179	 * Exported because it is the one string whose exact shape decides what lands on the
180	 * branch: a tab between the object id and the path, a NUL after each record. The `-z`
181	 * form is what makes a path with a space survive — the newline form would split it.
182	 */
183	export function indexInfoFor(entries: { blob: string; target: string }[]): string {
184	  return entries.map((entry) => `${DRAFT_FILE_MODE} blob ${entry.blob}\t${entry.target}\0`).join("");
185	}
