187	/** What one published draft resolves to before anything is pushed. */
188	export interface DraftFile {
189	  /** Absolute path of the local original, checked for readability. */
190	  source: string;
191	  /** Path on the branch, checked for the shape git accepts. */
192	  target: string;
193	}
194	
195	/**
196	 * Resolve the drafts a caller named, or say which one is unusable.
197	 *
198	 * Every refusal below is a hole that would otherwise be found after a push: a path
199	 * resolved against the wrong directory, a target that git will not accept, and two
200	 * drafts writing the same path — which would publish one file and report two.
201	 *
202	 * A relative `path` is resolved against `process.cwd()`, which is the work tree for
203	 * the same reason it is in `mcp/files.ts`: atoma starts every server as a child of the
204	 * run and inherits the directory the run was started in, which the runner starts at
205	 * the workspace root. A server started anywhere else resolves relative paths there,
206	 * and the refusal below says which directory that was rather than leaving the caller
207	 * to guess.
208	 */
209	export function resolveDraftFiles(files: { path: string; target: string }[]): DraftFile[] {
210	  const base = resolve(process.cwd());
211	  // The work tree and /tmp — the pinned interface: a draft is either a file in the
212	  // checkout or an absolute path under /tmp, which is where a conversion step puts its
213	  // output. `/tmp/atomaton-workspace` is the one subdirectory of it that survives a run.
214	  const roots = [base, "/tmp"];
215	  const seen = new Set<string>();
216	  const out: DraftFile[] = [];
217	
218	  for (const file of files) {
219	    const source = isAbsolute(file.path) ? resolve(file.path) : resolve(base, file.path);
220	    if (!roots.some((root) => source === root || source.startsWith(root + sep))) {
221	      throw new Error(
222	        `'${file.path}' resolves to '${source}', which is outside the places a draft may be read from ` +
223	          `(${roots.join(", ")}). Pass an absolute path, or one relative to ${base}.`,
224	      );
225	    }
226	    let size: number;
227	    try {
228	      const stats = statSync(source);
229	      if (!stats.isFile()) {
230	        throw new Error(`'${file.path}' is not a file (${source}); a draft is one file per target.`);
231	      }
232	      size = stats.size;
233	    } catch (error) {
234	      if (error instanceof Error && error.message.includes("is not a file")) throw error;
235	      throw new Error(`could not read '${file.path}': no such file at ${source}`);
236	    }
237	    if (size > MAX_READ_BYTES) {
238	      throw new Error(`${source} is ${size} bytes, past the ${MAX_READ_BYTES}-byte ceiling this tool publishes.`);
239	    }
240	    const target = normalizeTarget(file.target);
241	    if (seen.has(target)) {
242	      throw new Error(`two drafts target '${target}'; one would overwrite the other and the result would report both.`);
243	    }
244	    seen.add(target);
245	    out.push({ source, target });
246	  }
247	  return out;
248	}
