250	/**
251	 * The target as git will accept it, or the reason it will not.
252	 *
253	 * Checked here rather than left to `git update-index`, because git's answer to a bad
254	 * path is a warning on stderr and exit code 0 in one case (`Ignoring path /etc/x`):
255	 * the push would then succeed with the file simply absent, and the tool would report
256	 * a URL for a document that is not on the branch.
257	 */
258	function normalizeTarget(target: string): string {
259	  const trimmed = target.replace(/^\/+/, "");
260	  if (!trimmed) throw new Error("a draft's target cannot be empty.");
261	  if (isAbsolute(target) || target.startsWith("/")) {
262	    throw new Error(`target '${target}' must be relative to the branch, not absolute.`);
263	  }
264	  if (trimmed.startsWith("-")) {
265	    throw new Error(`target '${target}' starts with '-', which the index listing would read as an argument.`);
266	  }
267	  if (trimmed.includes("\\")) {
268	    throw new Error(`target '${target}' contains a backslash; branch paths are separated by '/'.`);
269	  }
270	  if (/[\t\n\r\0]/.test(trimmed)) {
271	    throw new Error(`target '${target}' contains a tab, newline or NUL, which the index listing cannot express.`);
272	  }
273	  const parts = trimmed.split("/");
274	  if (parts.some((part) => part === "" || part === "." || part === "..")) {
275	    throw new Error(`target '${target}' has an empty, '.' or '..' path segment, which git will not accept.`);
276	  }
277	  if (parts.some((part) => part.toLowerCase() === ".git")) {
278	    throw new Error(`target '${target}' is under .git, which git refuses to write a blob into.`);
279	  }
280	  return trimmed;
281	}
