355	/** The repository to upload against, as `owner/name`. */
356	function resolveRepo(): string {
357	  const fromEnv = (process.env.GITHUB_REPOSITORY ?? "").trim();
358	  if (fromEnv) return fromEnv;
359	  // Same fallback `mcp/github.ts` uses: the checkout's own remote.
360	  const { code, stdout } = gitRun("remote", "get-url", "origin");
361	  if (code === 0 && stdout) {
362	    const match = /github\.com[/:](.+\/.+?)(?:\.git)?$/.exec(stdout.trim());
363	    if (match) return match[1]!;
364	  }
365	  throw new Error(
366	    "GITHUB_REPOSITORY is unset and no GitHub remote could be read, so there is no repository to upload against.",
367	  );
368	}
