370	/** The repository's numeric REST id, which is what the endpoint routes by. */
371	function resolveRepositoryId(repo: string): number {
372	  const { code, stdout, stderr } = gh("api", `repos/${repo}`, "--jq", ".id");
373	  if (code !== 0) {
374	    throw new Error(`could not read the repository id for ${repo}: ${stderr || stdout}`);
375	  }
376	  const id = Number(stdout.trim());
377	  if (!Number.isFinite(id) || id <= 0) {
378	    throw new Error(`could not read the repository id for ${repo}: got ${stdout.trim().slice(0, 80)}`);
379	  }
380	  return id;
381	}
