387	 * credential — this is the "verify the shape here, the far end there" half of
388	 * a check that can only mean something after a merge.
389	 */
390	export function requestUrlFor(
391	  mode: ProbeMode,
392	  parts: { repositoryId?: number; name?: string; contentType: string },
393	): string {
394	  const query = new URLSearchParams();
395	  // The order gh uses: name, content_type, repository_id. An empty `name` is a
396	  // value, not an omission — it is what makes the 400 the endpoint's own
397	  // answer rather than a missing parameter.
398	  query.set("name", parts.name ?? "");
399	  query.set("content_type", parts.contentType);
400	  if (parts.repositoryId !== undefined) query.set("repository_id", String(parts.repositoryId));
401	  return `${UPLOAD_ENDPOINT}?${query.toString()}`;
402	}
