588	async function probe(a: z.infer<typeof PROBE_SCHEMA>): Promise<string> {
589	  const { token, kind } = credential();
590	  const mode = a.mode as ProbeMode;
591	  const contentType = a.content_type ?? "application/octet-stream";
592	
593	  const needsRepo = mode !== "routing";
594	  const repositoryId = a.repository_id ?? (needsRepo ? resolveRepositoryId(resolveRepo()) : undefined);
595	  // A caller's own `name` wins; without one the mode decides, which is what keeps
596	  // every existing call identical. `routing` with a name and no repository_id is the
597	  // measurement the empty-name form could not reach — measured, the endpoint answers
598	  // `Invalid name for request` 400 for an empty one before it ever routes, so the
599	  // routing question was never asked.
600	  const name = a.name ?? (mode === "upload" || mode === "oversize" ? basename(a.file ?? "") : undefined);
601	
602	  let body: Uint8Array | undefined;
603	  if (mode === "upload" || mode === "oversize") {
604	    if (!a.file) throw new Error(`mode ${mode} needs a file to send`);
605	    ({ bytes: body } = readFileFor(mode, a.file));
606	  }
607	
608	  const url = requestUrlFor(mode, { repositoryId, name, contentType });
609	
610	  const started = Date.now();
611	  log(`probe ${mode} ${body ? `${body.length}B` : "(no body)"}`);
612	  const response = await fetch(url, {
613	    method: "POST",
614	    headers: {
615	      // `token`, not `Bearer` — the prefix gh's own client sends, so the probe
616	      // measures the endpoint against the credential shape gh would have used.
617	      Authorization: `token ${token}`,
618	      "Content-Type": contentType,
619	      Accept: "application/vnd.github+json",
620	    },
